import numpy as np
from scipy.optimize import minimize

def objective(x):
    return - (np.sum(x)**2 + np.sum(x**2))

def constraint1(x):
    return 1 - np.abs(np.sum(x))

def constraint2(x):
    # Since we use bounds for x_i, we don't need this.
    return 0

def solve(n):
    # Maximize objective by minimizing -objective
    cons = [{'type': 'ineq', 'fun': constraint1}]
    bounds = [(-1, 1) for _ in range(n)]

    # Try different starting points
    max_val = -float('inf')
    for _ in range(10):
        x0 = np.random.uniform(-1, 1, n)
        res = minimize(objective, x0, method='SLSQP', bounds=bounds, constraints=cons)
        if res.success:
            max_val = max(max_val, -res.fun)
    return max_val

for n in range(20, 25):
    print(f"n={n}, max_f={solve(n)}")
